for w, v in zip(weights, values):
        if w > capacity:
            # Item alone exceeds capacity, cannot be taken
            continue
        # Update backwards to ensure each item is used at most once
        for c in range(capacity, w - 1, -1):
            candidate = dp[c - w] + v
            if candidate > dp[c]:
                dp[c] = candidate

